INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(21749, 'plPL', 'Na kolana!', '', 0),
(31397, 'plPL', 'Strażnicy miotu meldują się!', '', 0),
(31398, 'plPL', 'Strażnicy sanktuarium meldują się!', '', 0),
(31984, 'plPL', 'My... jesteśmy lepsi! Jak to... możliwe?', '', 0),
(31985, 'plPL', 'Niczego się nie boję! A już najmniej was!', '', 0),
(31986, 'plPL', 'Jesteście nic nieznaczący.', '', 0),
(31987, 'plPL', 'Cóż za mierny opór...', '', 0),
(31988, 'plPL', 'Łatwo was pokonać!', '', 0),
(31989, 'plPL', 'Ojciec dobrze mnie wyszkolił.', '', 0),
(31991, 'plPL', 'Zlituję się nad tobą, Sartharionie, ten jeden raz.', '', 0),
(31993, 'plPL', '', 'Nie ma tu dla was miejsca! Wasze miejsce jest... wśród zmarłych!', 0),
(31994, 'plPL', '', 'Żadna rywalizacja.', 0),
(31995, 'plPL', '', 'Jak zwykle. Akurat kiedy zaczynałam się dobrze bawić...', 0),
(31996, 'plPL', '', 'Skazuję was na ciemność.', 0),
(31997, 'plPL', '', 'Aroganckie stworzonka, rzucacie wyzwanie mocom, których jeszcze nie rozumiecie.', 0),
(31998, 'plPL', '', 'Nie jestem zwykłą smoczycą. Przekonacie się, że jestem kimś znacznie, znacznie potężniejszym.', 0),
(31999, 'plPL', '', 'Zabawnie jest patrzeć, jak się szamoczecie. Dobrze, patrzcie, jak to się robi!', 0),
(32000, 'plPL', '', 'Nie powinnam była... się powstrzymywać...', 0),
(32002, 'plPL', 'Nie stanowicie zagrożenia, pośledniejsze istoty! Dajcie z siebie wszystko!', '', 0),
(32003, 'plPL', 'Moglibyście przynajmniej stawić jakiś opór!', '', 0),
(32004, 'plPL', 'To wszystko, na co was stać?', '', 0),
(32005, 'plPL', 'Będę dłubał w zębach waszymi kośćmi!', '', 0),
(32006, 'plPL', 'Sprytni jesteście, co? Ja też mam w zanadrzu kilka sztuczek...', '', 0),
(32007, 'plPL', 'W przeciwieństwie do was mam wiele talentów!', '', 0),
(32008, 'plPL', 'Ojciec miał co do ciebie rację, Sartharionie. JESTEŚ słabeuszem.', '', 0),
(32009, 'plPL', 'Wciąż mam w sobie... trochę... sił-ł-ł...', '', 0),
(32554, 'plPL', '%s zaczyna otwierać portal zmierzchu!', '', 0),
(32958, 'plPL', 'W królestwie zmierzchu pojawia się uczeń Shadrona!', '', 0),
(32959, 'plPL', '', 'Tenebron zaczyna wysiadywać jaja w królestwie zmierzchu!', 0),
(32960, 'plPL', 'W królestwie zmierzchu pojawia się uczeń Vesperona!', '', 0);
